import sqlite3
import json
import re
from collections import defaultdict, Counter
from datetime import datetime

def parse_hours(hours_str):
    """Parse Yelp hours string into a dict of day -> (open, close) in minutes since midnight."""
    if not hours_str:
        return {}
    day_map = {
        'Monday': 0, 'Tuesday': 1, 'Wednesday': 2, 'Thursday': 3,
        'Friday': 4, 'Saturday': 5, 'Sunday': 6
    }
    hours_dict = {}
    for part in hours_str.split(','):
        if ':' not in part:
            continue
        day, time_range = part.strip().split(':', 1)
        if day not in day_map:
            continue
        open_time, close_time = time_range.strip().split('-')
        def time_to_minutes(t):
            # Handle cases like '12:30' or '23:00'
            if ':' not in t:
                return 0
            h, m = map(int, t.split(':'))
            return h * 60 + m
        open_min = time_to_minutes(open_time)
        close_min = time_to_minutes(close_time)
        hours_dict[day_map[day]] = (open_min, close_min)
    return hours_dict

def timestamp_to_day_hour(ts):
    """Convert ISO timestamp to (weekday, hour) tuple."""
    dt = datetime.fromisoformat(ts.replace('Z', '+00:00'))
    return dt.weekday(), dt.hour

def main():
    # Database paths
    sqlite_paths = {
        "business": "D:/Yelp-JSON/db/sqlite3/business.db",
        "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db"
    }

    # Step 1: Fetch restaurants with check-in data
    conn_business = sqlite3.connect(sqlite_paths['business'])
    conn_checkin = sqlite3.connect(sqlite_paths['checkin'])

    try:
        # Get restaurant businesses
        business_cursor = conn_business.cursor()
        business_cursor.execute("""
            SELECT business_id, name, hours
            FROM business
            WHERE categories LIKE ?
        """, ('%Restaurants%',))
        restaurants = {row[0]: {'name': row[1], 'hours': parse_hours(row[2])} for row in business_cursor.fetchall()}

        # Get check-in data for these restaurants
        checkin_cursor = conn_checkin.cursor()
        checkin_cursor.execute("""
            SELECT business_id, date
            FROM checkin
            WHERE business_id IN ({})
        """.format(','.join(['?'] * len(restaurants))), list(restaurants.keys()))

        # Aggregate check-ins by business and opening hour
        opening_hour_checkins = defaultdict(list)

        for business_id, date_str in checkin_cursor.fetchall():
            if business_id not in restaurants:
                continue
            hours = restaurants[business_id]['hours']
            if not hours:
                continue

            # Split multiple timestamps (Yelp stores them space-separated)
            timestamps = date_str.strip().split()
            for ts in timestamps:
                try:
                    weekday, hour = timestamp_to_day_hour(ts)
                    if weekday in hours:
                        open_hour = hours[weekday][0] // 60  # Convert minutes to hour
                        if hour == open_hour:
                            opening_hour_checkins[business_id].append(ts)
                except Exception:
                    continue

        # Compute average check-ins during opening hour
        avg_opening_checkins = {}
        for bid, ts_list in opening_hour_checkins.items():
            # Count unique days to avoid overcounting same day
            days = set(datetime.fromisoformat(ts.replace('Z', '+00:00')).date() for ts in ts_list)
            if len(days) > 0:
                avg_opening_checkins[bid] = len(ts_list) / len(days)

        # Sort by lowest average opening-hour crowd
        sorted_restaurants = sorted(avg_opening_checkins.items(), key=lambda x: x[1])

        # Output top 10 least crowded at opening
        print("Top 10 restaurants least crowded at opening time:")
        for i, (bid, avg_count) in enumerate(sorted_restaurants[:10]):
            print(f"{i+1}. {restaurants[bid]['name']} (avg {avg_count:.2f} check-ins at opening)")

    except Exception as e:
        print(f"Error: {e}")
    finally:
        conn_business.close()
        conn_checkin.close()

if __name__ == "__main__":
    main()
